def table(head, rows):
    out = ["| " + " | ".join(head) + " |", "|" + "|".join("---" for _ in head) + "|"]
    out += ["| " + " | ".join(str(c).replace("|", "/") for c in r) + " |" for r in rows]
    return out


def near(n, onsets, k=2):
    return sum(1 for t in range(1, n + 1) if any(abs(t - o) <= k for o in onsets))


def short(sha: str) -> str:
    return sha[:8]


ORDINALS = ["first", "second", "third", "fourth", "fifth", "sixth"]


def registration_ordinal(baseline: dict | None) -> tuple[int, str]:
    """which registration this is, from the baseline it supersedes (its summary.json, or the `baseline` entry of the changes): the first when nothing was committed before,
    else one more than the superseded one, which is itself preceded by `registered_before`"""
    if not baseline or not baseline.get("registered_in"):
        return 1, ORDINALS[0]
    n = len(baseline.get("registered_before") or []) + 2
    return n, ORDINALS[n - 1]


def earlier_text(prev: dict | None) -> str:
    """'the one against `cec1bba` (`74118b5`)' for each registration committed before the one superseded, newest first; '' when there is none"""
    return ", ".join(f"the one against `{e['speeds_kit'][:7]}` (`{e['commit'][:7]}`)" for e in ((prev or {}).get("baseline", {}).get("registered_before") or []))


def superseded_sentence(prev: dict, reg_in: str | None) -> str:
    """The Point's sentence about the registration this one supersedes (or replaced before it was pushed)"""
    was = prev["scripts"]["before"]["commit"][:7]
    if reg_in:
        word = registration_ordinal(prev["baseline"])[1]
        before = earlier_text(prev)
        return (f" A registration against `{was}` was committed (`{reg_in[:7]}`) and this one, the {word}, supersedes it." + (f" Before it came {before}." if before else "")
                + " All of them stay in the history; the pass is scored against this one, and the section after it says what moved since the one it supersedes.")
    return f" A registration against `{was}` was built and replaced before anything was pushed; the section after it says what moved since that one."


def top_five_sentence(prev: dict | None) -> str:
    """whether the five friction events with the highest p are the superseded registration's five (the changes table lists the item when they are not)"""
    if not prev:
        return ""
    was = prev["scripts"]["before"]["commit"][:7]
    moved = next((m for c in prev["changes"] for m in c["moved"] if m["key"] == "number:events:top_five"), None)
    if moved:
        return f"The top five changed since the registration for `{was}`: it had {moved['before']}; now {moved['after']}. "
    return f"These are the same five as in the registration for `{was}`. "


def lineage_sentence(inputs: dict) -> str:
    """When the snapshot's own commit changed none of the code the build reads: which commit that code is of, and that the snapshot's commit changed documents only (from `last_changed_by` of the inputs).
    Empty when the snapshot's commit changed the code, or when the inputs do not say.  What the commit changed is said, with its lines, in the history at the end."""
    sk = inputs["speeds_kit"]
    last, snap = sk.get("last_changed_by") or {}, sk["commit"]
    code = [rel for rel in (SCRIPT, MOCK, TAPGRADE_PY, PICKS_PY) if last.get(rel)]
    if not code or any(last[rel] == snap for rel in code):
        return ""
    names = {SCRIPT: "the script", MOCK: "the mock", TAPGRADE_PY: f"`{TAPGRADE_PY}`", PICKS_PY: f"`{PICKS_PY}`"}
    docs_changed = any(last.get(rel) == snap for rel in (TAPGRADE_MD, RUNBOOK))
    return (" The code the build reads was last changed by these commits: " + ", ".join(f"{names[rel]} by `{last[rel][:7]}`" for rel in code)
            + f"; the commit `{snap[:7]}` changed " + ("documents only" if docs_changed else "none of the files read") + ".")


