    def changes_section(ch, heading, point, before_label, closing, extra=None):
        w(heading)
        w("")
        w(point.format(n=ch["moved_count"], path=ch["baseline"]["path"]))
        w("")
        b0, t0 = ch["scripts"]["before"], ch["scripts"]["this"]
        grew = t0["lines"] - b0["lines"]
        for line in table(["", before_label, "This registration"], [
                ["speeds-kit commit", f"`{b0['commit'][:7]}`", f"`{t0['commit'][:7]}`"],
                ["script sha256", f"`{short(b0['sha256'])}…`", f"`{short(t0['sha256'])}…`"],
                ["script lines, build", f"{b0['lines']}, {b0['build']}", f"{t0['lines']}, {t0['build']} ({'+' if grew >= 0 else ''}{grew} lines)"],
                ["events", b0["events"], t0["events"]],
                ["findings of the checker", b0["findings"], t0["findings"]]]):
            w(line)
        w("")
        if extra:
            extra()
        for i, c in enumerate(ch["changes"], 1):
            w(f"**{i}. {c['change']}.**")
            w("")
            w(c["effect"])
            w("")
            if c["moved"]:
                rows = []
                for m in c["moved"]:
                    if m.get("banks"):
                        before, after = "; ".join(f"{b}: {v[0]}" for b, v in m["banks"].items()), "; ".join(f"{b}: {v[1]}" for b, v in m["banks"].items())
                    else:
                        before, after = m["before"], m["after"]
                    rows.append([m["what"], before, after, m["delta"] or "", m["why"]])
                for line in table(["What", before_label, "Now", "By how much", "Why"], rows):
                    w(line)
            else:
                w("Moved: nothing.")
            w("")
        w(closing)
        w("")

